           is_submitting,\n            is_loading,\n            removeMessages,\n            removeConfirmationMessages,\n            fp_config,\n            submit,\n            inputFields,\n            requiredComponent,\n        };\n    },\n    components: {\n        FormElement,\n    },\n};\n</script>\n\n<style scoped>\n.modal {\n    position: fixed;\n    z-index: 9998;\n    display: table;\n    transition: opacity 0.3s ease;\n    margin: auto;\n    padding: 20px 30px;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.33);\n    transition: all 0.3s ease;\n}\n#close_modal {\n    cursor: pointer;\n}\n\n.modal_centered {\n    position: fixed;\n    z-index: 9998;\n    display: table;\n    transition: opacity 0.3s ease;\n    left: 0px;\n    top: 0px;\n    width: 100%;\n    height: 100%;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.33);\n}\n.spinner {\n    position: absolute;\n    top: 50%;\n    left: 40%;\n    width: 10%;\n}\n\n.confirmation .inputs {\n    margin-top: 0.4em;\n}\n.confirmation .inputs input,\n:deep(.flatpickr-input) {\n    width: auto;\n    margin: 0px;\n    /* float: left; */\n}\n\n:deep(.flatpickr-input) {\n    padding-left: 20px;\n}\n\n.confirmation .inputs label {\n    padding: 0.4em;\n    /* float: right; */\n}\n\n:deep(.modal-body form .v-select) {\n    width: 50%;\n}\n\n:deep(.modal-body .v-select),\n:deep(\n    .modal-body\n        input:not([type=\"submit\"]):not([type=\"search\"]):not(\n            [type=\"button\"]\n        ):not([type=\"checkbox\"]):not([type=\"radio\"])\n),\n:deep(.modal-body textarea) {\n    min-width: 50%;\n}\n\n:deep(.modal-body .flatpickr-input) {\n    width: 50%;\n}\n</style>\n"],"sourceRoot":""}]);
