      row,\n                                                meta\n                                            ) {\n                                                return (\n                                                    '<a href=\"/cgi-bin/koha/erm/eholdings/local/resources/' +\n                                                    row.resource_id +\n                                                    '\" class=\"show\">' +\n                                                    escape_str(\n                                                        `${row.package.name} (#${row.package.package_id})`\n                                                    ) +\n                                                    \"</a>\"\n                                                );\n                                            },\n                                        },\n                                    ],\n                                    options: {\n                                        embed: \"package\",\n                                    },\n                                    url:\n                                        APIClient.erm.httpClient._baseURL +\n                                        \"eholdings/local/resources\",\n                                },\n                            },\n                            apiClient: {\n                                type: \"object\",\n                                value: APIClient.erm.localPackages,\n                            },\n                            filters: {\n                                type: \"filter\",\n                                keys: {\n                                    title_id: { property: \"title_id\" },\n                                },\n                            },\n                            resource: {\n                                type: \"resource\",\n                            },\n                            resourceName: {\n                                type: \"string\",\n                                value: \"package\",\n                            },\n                            resourceNamePlural: {\n                                type: \"string\",\n                                value: \"packages\",\n                            },\n                            hasAdditionalFields: {\n                                type: \"boolean\",\n                                value: true,\n                            },\n                        },\n                    },\n                    componentProps: {\n                        newRelationshipDefaultAttrs: {\n                            type: \"object\",\n                            value: {\n                                package_id: null,\n                                vendor_id: null,\n                                started_on: null,\n                                ended_on: null,\n                                proxy: \"\",\n                            },\n                        },\n                        resourceRelationships: {\n                            resourceProperty: \"resources\",\n                        },\n                        relationshipI18n: {\n                            nameUpperCase: $__(\"Package\"),\n                            removeThisMessage: $__(\"Remove this package\"),\n                            addNewMessage: $__(\"Add new package\"),\n                            noneCreatedYetMessage: $__(\n                                \"There are no packages created yet\"\n                            ),\n                        },\n                        fetchOptions: {\n                            type: \"boolean\",\n                            value: true,\n                        },\n                    },\n                    relationshipFields: [\n                        {\n                            name: \"package_id\",\n                            type: \"select\",\n                            label: $__(\"Package\"),\n           